<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import AssistantQuality from './AssistantQuality.vue';import {qualityStory} from '../../shared/assistant-quality.mjs';import {storyIntent,planStoryPages,storyboardPageGroups} from '../../shared/story-pages.mjs';
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';import {Plus,Send,Square,Settings,Download,Copy,PanelsTopLeft,X,LoaderCircle,Folder,ChevronDown,MoreHorizontal,ImagePlus,Trash2,FolderOpen,RefreshCw,SquarePen} from 'lucide-vue-next';import {useStudio,api,clone} from '../store';import {templatePanels} from '../editor/geometry';import {storyboardText} from '../../shared/storyboard.mjs';import LlmSettings from './LlmSettings.vue';
const s=useStudio();s.config.assistantUi||={draft:'',panels:4,mode:'story',settings:true};const prefs=computed(()=>s.config.assistantUi),state=ref({status:'idle'}),chats=ref([]),active=ref(null),conversation=ref(),eventSource=ref();const chat=computed(()=>chats.value.find(c=>c.id===active.value));const rawResult=computed(()=>prefs.value.editedStories?.[active.value]||(state.value.chatId===active.value&&state.value.result?state.value.result:[...(chat.value?.messages||[])].reverse().find(m=>m.result)?.result));
const result=computed(()=>{if(!rawResult.value)return null;const source=[...(chat.value?.messages||[])].reverse().find(message=>message.role==='user')?.content||'';const intent=storyIntent(source,{panelCount:rawResult.value.panels.length,pageCount:rawResult.value.pageCount});return planStoryPages(qualityStory(rawResult.value,s.config.llm,s.config.activeProfile),{pageCount:intent.pageCount});});
function emptyStarter(){const pages=s.project?.pages;return pages?.length===1&&!pages[0].objects.length&&['漫画页','Comic page'].includes(pages[0].name)&&pages[0].width===1200&&pages[0].height===1800;}
function targetPageLabel(panel){const imported=prefs.value.importedPages?.[active.value];const pageId=imported?.projectId===s.project?.id?imported.pages?.[panel.page]:null;const index=s.project?.pages.findIndex(page=>page.id===pageId)??-1;return index>=0?'已放入项目第 '+(index+1)+' 页':'将新增到项目第 '+((emptyStarter()?0:s.project?.pages.length||0)+panel.page)+' 页';}
const attachmentInput=ref();prefs.value.attachments||=[];
async function attach(files){const items=await s.importImages([...files].slice(0,6-prefs.value.attachments.length));prefs.value.attachments.push(...items.map(i=>i.id));if(s.config.llm.provider==='local'&&!s.config.llm.mmproj){const d=await api('assistant/models');const projects=d.models.filter(m=>m.mmproj);if(projects.length===1)s.config.llm.mmproj=projects[0].path;}}
const attachment=id=>s.gallery.find(i=>i.id===id);
const chatEdit=ref(null),chatDelete=ref(null),deleting=ref(false),refreshing=ref(false);prefs.value.folders||=[];prefs.value.chatMeta||={};prefs.value.promptTarget||='generate';
const targets=computed(()=>[{id:'generate',label:'当前单图生成',positive:s.p.positive,negative:s.p.negative},...(s.project?.pages||[]).flatMap(pg=>pg.objects.filter(o=>o.kind==='panel').map(o=>({id:o.id,label:pg.name+' / '+o.name,positive:o.positive||'',negative:o.negative||'',panel:o})))]);
const promptTarget=computed(()=>targets.value.find(t=>t.id===prefs.value.promptTarget)||targets.value[0]);
const chatName=c=>prefs.value.chatMeta[c.id]?.name||c.title;
const folderChats=id=>chats.value.filter(c=>{const folder=prefs.value.chatMeta[c.id]?.folder||'';return id?folder===id:!prefs.value.folders.some(f=>f.id===folder);});
function askDeleteGroup(f){chatDelete.value={groupId:f.id,name:f.name,chats:folderChats(f.id),ids:[]};chatEdit.value=null;}
function askDeleteChat(id){const c=chats.value.find(c=>c.id===id);if(c){chatDelete.value={name:chatName(c),chats:[c],ids:[id]};chatEdit.value=null;}}
async function confirmDelete(){if(deleting.value)return;deleting.value=true;await s.action(async()=>{try{await window.__mogeFlush?.();const d=chatDelete.value,data=await api('assistant/chats/delete',{ids:d.ids,...(d.groupId?{groupId:d.groupId}:{})});chats.value=data.chats;s.config.assistantUi=data.assistantUi;if(!chats.value.some(c=>c.id===active.value)){active.value=chats.value[0]?.id||null;state.value={status:'idle'};}chatDelete.value=null;s.notify(d.groupId?'对话组已删除，未勾选的对话已移到未分组':'对话已删除');}finally{deleting.value=false;}});}
async function refreshChats(){refreshing.value=true;try{await s.action(refresh);}finally{refreshing.value=false;}}
function saveChatEdit(){const e=chatEdit.value;if(!e?.name?.trim())return;if(e.kind==='folder'){if(e.id){const f=prefs.value.folders.find(f=>f.id===e.id);if(f)f.name=e.name.trim();}else prefs.value.folders.push({id:crypto.randomUUID(),name:e.name.trim(),collapsed:false});}else prefs.value.chatMeta[e.id]={name:e.name.trim(),folder:e.folder||''};chatEdit.value=null;}
function newConversation(folder=''){active.value=null;prefs.value.newChatFolder=folder;}
function selectChat(c){active.value=c.id;prefs.value.newChatFolder='';}
function editChat(c){chatEdit.value={kind:'chat',id:c.id,name:chatName(c),folder:prefs.value.chatMeta[c.id]?.folder||''};}
function applyOptimized(){const p=result.value?.panels[0],t=promptTarget.value;if(!p)return;if(t.panel){t.panel.positive=p.positive;t.panel.negative=p.negative;s.notify('已更新 '+t.label);}else usePrompt(p);}
let initialChatsLoaded=false;
async function refresh(){const data=await api('assistant/models');chats.value=data.chats;state.value=data.state;if(!initialChatsLoaded){active.value=data.state.chatId||chats.value[0]?.id||null;initialChatsLoaded=true;}else if(active.value&&!chats.value.some(c=>c.id===active.value))active.value=null;}
onMounted(async()=>{await s.action(refresh);eventSource.value=new EventSource('/api/events');eventSource.value.onmessage=e=>{const event=JSON.parse(e.data);if(event.type==='assistant'){state.value=event.data;if(['done','error','cancelled'].includes(event.data.status))void refresh();nextTick(()=>conversation.value?.scrollTo({top:conversation.value.scrollHeight,behavior:'smooth'}));}};});onUnmounted(()=>eventSource.value?.close());
function saveEdited(){if(result.value&&active.value)(prefs.value.editedStories||(prefs.value.editedStories={}))[active.value]=clone(result.value);}
async function send(){if(!prefs.value.draft.trim())return;await s.action(async()=>{if(active.value&&prefs.value.editedStories)delete prefs.value.editedStories[active.value];const wasNew=!active.value;const text=prefs.value.mode==='prompt'?`优化目标：${promptTarget.value.label}。修改要求：${prefs.value.draft}\n现有正面提示词：${promptTarget.value.positive}\n现有负面提示词：${promptTarget.value.negative}`:prefs.value.draft,data=await api('assistant/submit',{text,panelCount:prefs.value.panels,pageCount:prefs.value.pageCount||0,mode:prefs.value.mode,chatId:active.value,imageIds:[...prefs.value.attachments]});prefs.value.attachments=[];active.value=data.chatId;if(wasNew&&prefs.value.newChatFolder)(prefs.value.chatMeta[data.chatId]||={}).folder=prefs.value.newChatFolder;prefs.value.newChatFolder='';prefs.value.draft='';await refresh();});}
async function copy(text){await navigator.clipboard.writeText(text);s.notify('已复制');}
function usePrompt(p){s.p.positive=p.positive;s.p.negative=p.negative;s.tab='generate';s.notify('已导入这格的提示词');}
async function exportTxt(){if(result.value)await s.exportFile(result.value.title+'-分镜提示词.txt',new Blob([storyboardText(result.value)],{type:'text/plain;charset=utf-8'}));}
function makePage(show=true){
 if(!result.value)return[];const story=result.value;if(!s.project)s.newProject();
 const previous=prefs.value.importedPages?.[active.value];
 if(previous?.projectId===s.project.id){const existing=Object.values(previous.pages).map(id=>s.project.pages.find(page=>page.id===id));if(existing.length===story.pageCount&&existing.every(Boolean)){if(show){s.config.editorPrefs={...s.config.editorPrefs,pageIndex:s.project.pages.findIndex(page=>page.id===existing[0].id),selected:'canvas'};s.tab='comic';}return existing;}}
 const pages=storyboardPageGroups(story).map(group=>{const page=s.newPage();page.name=story.title+' · 第'+group.page+'页';const count=group.panels.length,layout=count===1?'single':count<=3?'strip':count<=4?'four':'six';let positions=templatePanels(layout,page.width,page.height);if(count>6){const cols=3,rows=Math.ceil(count/cols),gap=22,margin=45,w=(page.width-margin*2-gap*(cols-1))/cols,h=(page.height-margin*2-gap*(rows-1))/rows;positions=group.panels.map((_,i)=>{const x=margin+(i%cols)*(w+gap),y=margin+Math.floor(i/cols)*(h+gap);return[{x,y},{x:x+w,y},{x:x+w,y:y+h},{x,y:y+h}];});}
 page.objects=group.panels.map((p,i)=>({id:crypto.randomUUID(),kind:'panel',name:'第'+group.page+'页 · 第'+p.position+'格 · '+p.title,storyPanelIndex:story.panels.findIndex(item=>item.page===p.page&&item.position===p.position),points:positions[i],fill:'#f6f5fa',border:'#242633',borderWidth:4,image:null,imageScale:1,imageX:0,imageY:0,rotation:0,visible:true,positive:p.positive,negative:p.negative,description:p.description,dialogue:p.dialogue}));return page;});
 if(emptyStarter())s.project.pages.splice(0,1,...pages);else s.project.pages.push(...pages);if(active.value)(prefs.value.importedPages||(prefs.value.importedPages={}))[active.value]={projectId:s.project.id,pages:Object.fromEntries(pages.map((page,i)=>[i+1,page.id]))};s.config.editorPrefs={...s.config.editorPrefs,pageIndex:s.project.pages.length-pages.length,selected:'canvas'};
 if(show){s.tab='comic';s.notify('已创建 '+pages.length+' 页，共 '+story.panels.length+' 格，已按标注页码放入。');}return pages;
}
async function generateAll(){await s.action(async()=>{const pages=makePage(false);if(!pages.length)return;const all=pages.flatMap(page=>page.objects.filter(panel=>panel.kind==='panel').map(panel=>({page,panel})));for(const [index,{panel}] of all.entries()){const part=result.value?.panels[index];if(part){panel.positive=part.positive;panel.negative=part.negative;}const p=clone(s.p);p.positive=panel.positive;p.negative=panel.negative;await api('models/prepare',{params:p});}await s.startEngine();if(s.engine.state!=='ready')return;for(const {page,panel} of all){const p=clone(s.p);p.positive=panel.positive;p.negative=panel.negative;p.batch=1;p.width=832;p.height=1248;await api('jobs',{params:p,count:1,target:{projectId:s.project.id,pageId:page.id,panelId:panel.id}});}s.tab='comic';s.notify(pages.length+' 页、'+all.length+' 格已全部加入队列，完成后按页填图。');});}

</script>
<template><div v-resize-panels="{key:'assistant',config:s.config,min:[130,300,250],labels:['调整对话列表宽度','调整模型设置宽度']}" :class="['assistant-workspace',{'settings-open':prefs.settings}]"><aside class="assistant-chats card">
<button class="primary" @click="newConversation()"><Plus :size="16"/>{{ui("新建对话")}}</button>
<button class="secondary" @click="chatEdit={kind:'folder',name:''}"><Folder :size="15"/>{{ui("新建对话组")}}</button>
<div class="assistant-list-tools"><button class="quiet" :title="ui(&quot;打开本地对话文件夹（works/assistant）&quot;)" @click="s.action(()=>s.openFolder('assistant'))"><FolderOpen :size="14"/>{{ui("本地文件夹")}}</button><button class="icon-button" :title="ui(&quot;刷新对话列表&quot;)" :aria-busy="refreshing" :disabled="refreshing" @click="refreshChats"><RefreshCw :size="14"/></button></div>
<section v-for="f in prefs.folders" :key="f.id" class="chat-folder"><div class="button-row"><button class="quiet" :title="ui(f.name)" @click="f.collapsed=!f.collapsed"><ChevronDown :size="13" :style="{transform:f.collapsed?'rotate(-90deg)':''}"/><Folder :size="14"/><span>{{f.name}}</span></button><button class="icon-button" :title="ui(&quot;管理对话组&quot;)" @click="chatEdit={kind:'folder',id:f.id,name:f.name}"><MoreHorizontal :size="14"/></button><button class="icon-button" :title="ui(&quot;在此对话组新建对话&quot;)" @click="newConversation(f.id)"><SquarePen :size="14"/></button></div><template v-if="!f.collapsed"><div v-for="c in folderChats(f.id)" :key="c.id" :class="['assistant-chat-entry',{active:active===c.id}]"><button :title="ui(chatName(c))" @click="selectChat(c)"><strong>{{chatName(c)}}</strong></button><button class="icon-button" :title="ui(&quot;管理对话&quot;)" @click="editChat(c)"><MoreHorizontal :size="14"/></button></div></template></section>
<div class="assistant-ungrouped">{{ui("未分组")}}</div><div v-for="c in folderChats('')" :key="c.id" :class="['assistant-chat-entry',{active:active===c.id}]"><button :title="ui(chatName(c))" @click="selectChat(c)"><strong>{{chatName(c)}}</strong></button><button class="icon-button" :title="ui(&quot;管理对话&quot;)" @click="editChat(c)"><MoreHorizontal :size="14"/></button></div>
</aside><section class="assistant-main card"><div class="card-heading"><div><strong>{{ui("提示词助手")}}</strong><span v-if="!active&&prefs.newChatFolder" class="badge">{{ui("新对话 · ")}}{{prefs.folders.find(f=>f.id===prefs.newChatFolder)?.name}}</span><span class="badge">{{ui(s.config.llm?.provider==='deepseek'?'DeepSeek 线上':'本地 GGUF')}}</span></div><button class="icon-button" :title="ui(&quot;模型与 API 设置&quot;)" @click="prefs.settings=!prefs.settings"><Settings :size="18"/></button></div><div ref="conversation" class="assistant-conversation"><p v-if="!chat&&!result" class="assistant-intro">{{ui("用平常说话的方式描述人物、动作和故事。助手会整理成分镜，为每格写好 Anima 标签与自然语言提示词。")}}</p><div v-for="message in chat?.messages.filter(m=>m.role==='user')" class="user-message"><div v-if="message.imageIds?.length" class="assistant-attachments"><img v-for="id in message.imageIds" :src="attachment(id)?.url" :alt="ui(&quot;参考图片&quot;)"/></div>{{message.content}}</div><div v-if="state.status==='running'&&state.chatId===active" class="assistant-progress"><LoaderCircle class="spin" :size="18"/>{{ui(state.message)}}<details v-if="state.partial"><summary>{{ui("查看正在生成的内容")}}</summary><pre>{{state.partial}}</pre></details></div><p v-if="['error','cancelled'].includes(state.status)&&state.chatId===active" class="error-note">{{ui(state.message)}}</p><template v-if="result"><div class="story-result-heading"><h2>{{result.title}}</h2><p>{{result.summary}}</p><div class="button-row"><button class="primary" @click="makePage()"><PanelsTopLeft :size="16"/>{{ui("创建 ")}}{{ui(result.pageCount)}}{{ui(" 页漫画分镜")}}</button><button class="secondary" @click="generateAll" :disabled="state.status==='running'">{{ui("一键生成全部分镜")}}</button><button class="secondary" @click="exportTxt"><Download :size="15"/>{{ui("导出 TXT")}}</button></div></div><article v-for="(p,i) in result.panels" class="story-panel-result"><div class="button-row"><h3>{{ui("第 ")}}{{ui(p.page)}}{{ui(" 页 · 第 ")}}{{ui(p.position)}}{{ui(" 格 · ")}}{{p.title}}</h3><span class="story-page-target">{{targetPageLabel(p)}}</span><span class="badge">{{p.shot}}</span></div><p>{{p.description}}</p><label>{{ui("正面提示词")}}<textarea v-model="p.positive" @input="saveEdited" rows="5"/></label><details><summary>{{ui("负面提示词与对白")}}</summary><label>{{ui("负面提示词")}}<textarea v-model="p.negative" @input="saveEdited" rows="2"/></label><label>{{ui("对白")}}<textarea v-model="p.dialogue" @input="saveEdited" rows="2"/></label></details><div class="button-row"><button class="secondary" @click="copy(p.positive)"><Copy :size="14"/>{{ui("复制提示词")}}</button><button class="primary" @click="usePrompt(p)">{{ui("用于单图生成")}}</button></div></article></template></div><div class="assistant-composer"><div class="assistant-composer-scroll"><AssistantQuality/><div class="button-row"><select v-model="prefs.mode"><option value="story">{{ui("自动写分镜")}}</option><option value="prompt">{{ui("优化单张提示词")}}</option></select><select v-if="prefs.mode==='prompt'" v-model="prefs.promptTarget" :aria-label="ui(&quot;选择要优化的提示词&quot;)"><option v-for="t in targets" :value="t.id">{{ui(t.label)}}</option></select><button v-if="prefs.mode==='prompt'&&result" class="secondary" @click="applyOptimized">{{ui("应用到所选目标")}}</button><label v-if="prefs.mode==='story'" class="inline-label">{{ui("分镜数")}}<input type="number" v-model.number="prefs.panels" min="1" max="12"/></label><span class="muted">{{ui(s.config.llm?.provider==='deepseek'?'描述将发送到 DeepSeek 官方接口':'本机推理，故事不上传')}}</span></div><div v-if="prefs.attachments.length" class="assistant-attachments"><div v-for="(id,i) in prefs.attachments"><img :src="attachment(id)?.url" :alt="ui(&quot;待发送参考图片&quot;)"/><button class="icon-button" :title="ui(&quot;移除参考图片&quot;)" @click="prefs.attachments.splice(i,1)"><X :size="13"/></button></div></div><input ref="attachmentInput" type="file" class="hidden" accept="image/png,image/jpeg,image/webp" multiple @change="s.action(()=>attach($event.target.files));$event.target.value=''"/><textarea @paste="if($event.clipboardData.files.length){$event.preventDefault();s.action(()=>attach($event.clipboardData.files))}" v-model="prefs.draft" :aria-label="ui(&quot;故事或动作描述&quot;)" rows="3" :placeholder="ui(&quot;例如：一位穿红色外套的成年旅行者沿河散步，把纸舟放入水中，最后迎着晨光微笑。画四格，温暖治愈。&quot;)" @keydown.ctrl.enter="send"/></div><div class="button-row assistant-composer-actions"><button class="secondary" @click="attachmentInput.click()" :disabled="prefs.attachments.length>=6"><ImagePlus :size="16"/>{{ui("添加图片")}}</button><span class="muted">{{ui("可粘贴图片 · Ctrl＋Enter 发送 · 自动保存")}}</span><button v-if="state.status==='running'" class="secondary push" @click="s.action(()=>api('assistant/stop',{}))"><Square :size="15"/>{{ui("停止")}}</button><button v-else class="primary push" @click="send" :disabled="!prefs.draft.trim()"><Send :size="16"/>{{ui("生成分镜与提示词")}}</button></div></div></section><aside v-if="prefs.settings" class="assistant-settings card"><div class="card-heading"><strong>{{ui("模型与 API")}}</strong><button class="icon-button" @click="prefs.settings=false"><X :size="17"/></button></div><LlmSettings hide-quality/></aside><div v-if="chatEdit" class="modal-backdrop" @click.self="chatEdit.name?.trim()?saveChatEdit():chatEdit=null"><section class="modal" role="dialog" :aria-label="ui(&quot;管理对话&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭对话管理&quot;)" @click="chatEdit=null"><X :size="20"/></button></div><div class="modal-title"><h3>{{ui(chatEdit.kind==='folder'?'管理对话组':'管理对话')}}</h3></div><label>{{ui("名称")}}<input v-model="chatEdit.name" @keydown.enter="saveChatEdit"/></label><label v-if="chatEdit.kind==='chat'">{{ui("所在对话组")}}<select v-model="chatEdit.folder"><option value="">{{ui("未分组")}}</option><option v-for="f in prefs.folders" :value="f.id">{{f.name}}</option></select></label><div class="button-row"><button v-if="chatEdit.id" class="quiet danger" @click="chatEdit.kind==='folder'?askDeleteGroup(chatEdit):askDeleteChat(chatEdit.id)"><Trash2 :size="15"/>{{ui(chatEdit.kind==='folder'?'删除对话组':'删除对话')}}</button><button class="secondary push" @click="chatEdit=null">{{ui("取消")}}</button><button class="primary" @click="saveChatEdit">{{ui("保存")}}</button></div></section></div><div v-if="chatDelete" class="modal-backdrop" @click.self="!deleting&&(chatDelete=null)"><section class="modal assistant-delete-modal" role="dialog" :aria-label="ui(&quot;删除对话&quot;)"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭对话删除确认&quot;)" @click="chatDelete=null"><X :size="20"/></button></div><div class="modal-title"><h3>{{ui(chatDelete.groupId?'删除对话组':'删除对话')}} · {{ui(chatDelete.name)}}</h3></div><p>{{ui(chatDelete.groupId?'勾选要一并删除的对话，未勾选的对话会自动移到“未分组”。':'确认删除这条对话及其分镜记录？')}}</p><div v-if="chatDelete.groupId" class="assistant-delete-list"><label v-for="c in chatDelete.chats" :key="c.id"><input type="checkbox" v-model="chatDelete.ids" :value="c.id" :disabled="deleting"/><span :title="ui(chatName(c))">{{chatName(c)}}</span></label><p v-if="!chatDelete.chats.length" class="muted">{{ui("此对话组中没有对话。")}}</p></div><p class="muted">{{ui("删除前会在本地 trash 文件夹保留备份。")}}</p><div class="button-row"><button class="secondary" :disabled="deleting" @click="chatDelete=null">{{ui("取消")}}</button><button class="primary" :disabled="deleting" :aria-busy="deleting" @click="confirmDelete"><LoaderCircle v-if="deleting" class="spin" :size="15"/>{{ui(deleting?'正在删除…':chatDelete.groupId?'删除对话组'+(chatDelete.ids.length?'及 '+chatDelete.ids.length+' 条对话':''):'确认删除')}}</button></div></section></div></div></template>
